    clearTimeout(syncTimer);closeSheets();closeModal();
    ROPES=clone(originalRopes);ROPE_DETAIL=clone(originalRopeDetails);REVIEWS=clone(originalReviews);historyRecords=[];activeRope=ROPES[0];S.ship=A_SHIP;
