  function addRope(){
    if(!isCachedShip()){toast('本船档案尚未缓存','warn');return;}
    var id=$('#nrNfc').textContent.trim().toUpperCase();
    if(!/^[A-Z0-9-]{3,36}$/.test(id)||id.indexOf('—')>=0){toast('请先扫描或输入 NFC 编号','warn');return;}
    if(ROPES.some(function(r){return r.id===id||ROPE_DETAIL[r.id]?.code===$('#nrCode').textContent;})){toast('NFC 或产品编号已存在，请核对后重试','bad');return;}
    var values=$$('.screen[data-s="newrope"] .fieldrow .fv>span').map(function(el){return el.textContent.trim();});
    var r={id:id,name:values[2],spec:values[3],mat:values[4],maker:values[7],loc:values[9],area:values[9].indexOf('艉')>=0?'艉部':values[9].indexOf('舷')>=0?'舷侧':'艏部',crew:values[10],status:'warn',due:'2026-11-15',last:''};
    openModal('写入标签','模拟将档案与 NFC 编号 '+id+' 绑定。',function(){
      ROPE_DETAIL[id]={code:values[1],mbl:values[5],mfg:values[6],inst:'—'};
      ROPES.push(r);
      go('list',{force:true});renderList();toast('已保存档案并模拟写入标签');
    },'模拟写入','取消');
  }

