  Object.values(TYPES).forEach(function(t){t.fields.forEach(function(f){if(['记录日期','检查日期','执行日期'].includes(f[0]))f[1]=TODAY;});});
  S.queue.forEach(function(q,i){q.date=['2026-11-03','2026-11-03','2026-11-02','2026-10-30'][i];if(i<3)q.at=['11-03 09:12','11-03 09:34','11-02 16:20'][i];});
  REVIEWS.forEach(function(r){r.at=r.date.slice(5)+' '+(r.at.match(/\d{2}:\d{2}/)||['09:05'])[0];});
  var v6SignedPerson=currentPerson;
