  function visibleAudit(){return !isCachedShip()?[]:S.role==='admin'?V5.auditHistory:V5.auditHistory.filter(function(r){return r.by===currentPerson().name;});}
  function visibleQueue(){return isCachedShip()?S.queue:[];}
  function pendingQueue(){return visibleQueue().filter(function(q){return q.state!=='done';});}
  function glyph(k){
    if(k==='overdue'||k==='due')return '<span class="v6-glyph '+k+'" aria-hidden="true"><i class="sig '+(k==='overdue'?'bad':'warn')+'"></i></span>';
    return '<span class="v6-glyph '+k+'" aria-hidden="true">'+icon({maint:'wrench',use:'clock',inci:'alert',review:'shield',todo:'v6-todo'}[k],'xs')+'</span>';
  }
  function soundGlyph(mode){return icon(mode==='silent'?'v6-mute':mode==='vibrate'?'v6-vibrate':'bell','sm');}
  var symbols='<symbol id="i-v6-vibrate" viewBox="0 0 24 24"><rect x="8" y="4" width="8" height="16" rx="2"/><path d="m5 6-2 3 2 3-2 3 2 3m14-12 2 3-2 3 2 3-2 3M11 17h2"/></symbol>'+
    '<symbol id="i-v6-mute" viewBox="0 0 24 24"><path d="M9 5a5 5 0 0 1 8 4c0 3 1 5 2 6M6 9c0 4-1 5-2 7h12m-6 4h4M3 3l18 18"/></symbol>'+
    '<symbol id="i-v6-todo" viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="3"/><path d="m7 12 3 3 7-7"/></symbol>';
  $('svg defs').insertAdjacentHTML('beforeend',symbols);

  go=function(name,opts){
    if(!isCachedShip()&&['detail','overview','photo','summary','newrope'].includes(name)){
      toast(L('暂无可用缆绳档案，请先登录并加入团队。','No rope records. Sign in and join a team to continue.'),'warn');name='list';
    }
    oldGo(name,opts);
    if(S.screen!==name)return;
    $$('.tab[data-nav]').forEach(function(b){if(b.dataset.nav===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
    if(name==='home')refreshHome();
    if(name==='me')renderMe();
    if(name==='team')renderTeam();
    if(name==='alerts')renderCal();
    if(name==='sync')renderQueue();
    if(name==='review')renderReview();
    if(name==='summary')renderSummary();
    if(name==='login')renderLogin();
    requestLanguage();
  };
  setRole=function(role){
    if(S.dirty&&S.role!==role){openModal(L('离开未保存记录？','Leave this unsaved record?'),L('切换账号后，本次未保存的内容需要重新填写。','Unsaved edits will be lost when you switch accounts.'),function(){S.dirty=false;resetDraft();setRole(role);go('me',{force:true});},L('离开并切换','Switch account'),L('继续填写','Keep editing'));return;}
    V6.signedIn=true;V5.account=role;S.role=role;
    if(role==='crew')S.ship=A_SHIP;
    ['Admin','Crew'].forEach(function(k){var on=role===k.toLowerCase();$('#rb'+k).classList.toggle('on',on);$('#rb'+k).setAttribute('aria-pressed',String(on));});
    refreshHome();renderList();renderQueue();renderReview();renderMe();renderTeam();renderCal();requestLanguage();
  };
  function logOut(){
    if(S.dirty){openModal(L('退出登录？','Sign out?'),L('当前记录尚未保存。','This record has not been saved.'),function(){S.dirty=false;resetDraft();logOut();},L('退出登录','Sign out'),L('继续填写','Keep editing'));return;}
    V6.signedIn=false;S.role='guest';closeSheets();closeModal();
    $('#rbAdmin').classList.remove('on');$('#rbCrew').classList.remove('on');
    renderList();renderQueue();renderReview();renderMe();renderTeam();renderCal();go('home',{force:true});toast(L('已退出登录，可继续浏览功能。','Signed out. You can still browse the app.'));
  }
  function emptyAction(){
    return '<button class="btn ghost" data-v6="'+(!V6.signedIn?'login':hasTeam()?'choose-ship':'join')+'">'+L(!V6.signedIn?'登录账号':hasTeam()?'切换船舶':'加入团队',!V6.signedIn?'Sign in':hasTeam()?'Switch vessel':'Join a team')+'</button>';
  }
  function emptyCopy(){return L(!V6.signedIn?'登录并加入船舶团队后，这里会显示缆绳资料。':hasTeam()?'本船档案尚未缓存，可切换至已缓存的示例船舶。':'尚未加入船舶团队，加入后可查看本船缆绳资料。',!V6.signedIn?'Sign in and join a vessel team to view rope records.':hasTeam()?'No cached records for this vessel. Switch to the cached demo vessel.':'Join your vessel team to see its rope records.');}
  function homeCounts(){
    return {
      sync:pendingQueue().filter(function(q){return queueDate(q)<=TODAY;}).length,
      review:visibleReviews().filter(function(r){return r.date<=TODAY;}).length,
      reminders:allEvents().filter(function(e){return e.pending&&!e.done&&e.date<=TODAY;}).length
    };
  }
  refreshHome=function(){
    var data=isCachedShip(),n=data?ROPES.length:hasTeam()?6:0,c=homeCounts();
    $('#shipName').textContent=hasTeam()?S.ship:L('尚无所属船舶','No vessel selected');
    $('.ship').setAttribute('aria-label',L('切换船舶','Switch vessel'));
    $('#homeCount').textContent=n;$('#homeAll').textContent=n;
    $('#homeStockLabel').textContent=data?L('按位置管理','By location'):L(hasTeam()?'档案未缓存':'暂无缆绳',hasTeam()?'Not cached':'No ropes');
    $('#homeCache').hidden=data||!hasTeam();
    $('.statcard .seg').style.display=n&&data?'flex':'none';
    $('.statcard .legend').style.display='flex';
    ['ok','warn','bad'].forEach(function(k,i){var count=data?ROPES.filter(function(r){return r.status===k;}).length:0;$('#stock'+k).textContent=count;$('.statcard .seg').children[i].style.width=n?count/n*100+'%':'0%';});
    $('#homeCutoff').textContent=L('截至今日（'+TODAY+'）仍未完成','Outstanding as of today · '+TODAY);
    var rows=[
      ['sync','sync',L('记录同步中心','Record sync'),L(c.sync?'已保存在本机，等待上传':'暂无未同步记录',c.sync?'Saved on device · awaiting upload':'No records awaiting sync'),c.sync],
      ['review','shield',L('记录审核','Record review'),L(c.review?'提交后尚未完成审核':'暂无待审核记录',c.review?'Submitted · awaiting review':'No records awaiting review'),c.review],
      ['reminders','bell',L('提醒','Reminders'),L(c.reminders?'已到期且尚未处理的事项':'暂无到期未处理事项',c.reminders?'Due and not yet completed':'No outstanding items due'),c.reminders]
    ];
    $('#homeModules').innerHTML=rows.map(function(r){return '<button class="v6-home-module" data-v6="home-'+r[0]+'" aria-label="'+r[2]+' '+r[4]+'"><span class="v6-module-icon">'+icon(r[1],'sm')+'</span><span class="tx"><b>'+r[2]+'</b><small>'+r[3]+'</small></span><span class="qty">'+r[4]+'</span>'+icon('right','xs')+'</button>';}).join('');
    $$('#sheetShip [data-act=pickship]').forEach(function(b){var on=b.dataset.v===S.ship;b.setAttribute('aria-pressed',String(on));b.querySelector('.ship-picked').hidden=!on;});
    requestLanguage();
  };
  var v6RenderList=renderList;
