  var textMemory=new WeakMap(),attrMemory=new WeakMap(),languageObserver;
  function englishText(value){
    if(UI_TEXT[value])return UI_TEXT[value];
    if(UI_TEXT[value.trim()])return value.replace(value.trim(),UI_TEXT[value.trim()]);
    var keys=Object.keys(UI_TEXT).filter(function(k){return k.length>1;}).sort(function(a,b){return b.length-a.length;});
    var out=value;keys.forEach(function(k){out=out.split(k).join(UI_TEXT[k]);});
    return out.replace(/(\d+) 条记录/g,'$1 records').replace(/(\d+) 条待审/g,'$1 pending').replace(/(\d+) 条历史/g,'$1 past').replace(/(\d+) 张照片/g,'$1 photos').replace(/(\d+) 张/g,'$1 photos').replace(/(\d+) 根/g,'$1 ropes').replace(/(\d+) 份/g,'$1 files').replace(/(\d+) 人/g,'$1 members').replace(/(\d+) 项/g,'$1 items').replace(/(\d+) 处/g,'$1 entries').replace(/(\d+) 秒后重发/g,'Resend in $1s').replace(/(\d{4}) 年 (\d+) 月/g,'$1 / $2');
  }
  function translateNode(node){
    var val=node.nodeValue;if(!val||!val.trim())return;
    if(node.parentElement.closest('script,style,textarea,input,[data-user-content]'))return;
    var old=textMemory.get(node);
    if(V6.lang==='zh'){
      if(old&&val===old.en){node.nodeValue=old.zh;}return;
    }
    if(old&&val===old.en)return;
    var next=englishText(val);
    if(next!==val){textMemory.set(node,{zh:val,en:next});node.nodeValue=next;}
  }
  function applyLanguage(){
    V6.langPending=false;
    if(languageObserver)languageObserver.disconnect();
    $$('option:not([value])',$('.app')).forEach(function(o){o.setAttribute('value',o.textContent);});
    var walker=document.createTreeWalker($('.app'),NodeFilter.SHOW_TEXT),node;
    while(node=walker.nextNode())translateNode(node);
    $$('[aria-label],[placeholder],[title]', $('.app')).forEach(function(el){
      var mem=attrMemory.get(el)||{};
      ['aria-label','placeholder','title'].forEach(function(k){
        var value=el.getAttribute(k);if(!value)return;
        if(V6.lang==='zh'){if(mem[k]&&value===mem[k].en)el.setAttribute(k,mem[k].zh);}
        else if(!mem[k]||value!==mem[k].en){var next=englishText(value);if(next!==value){mem[k]={zh:value,en:next};el.setAttribute(k,next);}}
      });attrMemory.set(el,mem);
    });
    if(languageObserver)languageObserver.observe($('.app'),{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['aria-label','placeholder','title']});
  }
  function requestLanguage(){
    if(V6.langPending)return;V6.langPending=true;queueMicrotask(applyLanguage);
  }
  function setLanguage(lang){
    V6.lang=lang==='en'?'en':'zh';document.documentElement.lang=V6.lang==='en'?'en':'zh-CN';
    applyLanguage();refreshHome();renderCal();renderMe();renderReview();
    if(S.screen==='team')renderTeam();if(S.screen==='login')renderLogin();requestLanguage();
  }
  languageObserver=new MutationObserver(requestLanguage);
  languageObserver.observe($('.app'),{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['aria-label','placeholder','title']});
  CAL_SEL=TODAY;


  /* v0.7: selected-day items, accessible multi-select legends and offline help. */
  var V7={selectedDate:TODAY,types:[],helpKey:'app',faqOpen:[0]};
  NOTAB.push('help','helpdetail');
  var categoryEn={overdue:'Overdue',due:'Due',maint:'Maintenance',use:'Use',inci:'Incident',review:'Review',todo:'To-do'};
  var kindOrder=['overdue','due','maint','use','inci','review','todo'];
  function categoryName(k){return L(CAT[k],categoryEn[k]);}
  function selectedDateLabel(){
    var date=V7.selectedDate||CAL_SEL||TODAY;
    return L(+date.slice(5,7)+' 月 '+(+date.slice(8))+' 日事项',new Date(date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'})+' items');
  }
  function rangeEvents(){
    return allEvents().filter(function(e){
      return V6.period==='day'?e.date===(V7.selectedDate||CAL_SEL):V6.period==='today'?e.date===TODAY:V6.period==='week'?withinWeek(e.date):e.date.slice(0,7)===monthKey();
    }).sort(function(a,b){return a.date.localeCompare(b.date)||a.id.localeCompare(b.id);});
  }
  periodEvents=function(){return rangeEvents().filter(function(e){return !V7.types.length||V7.types.includes(e.kind);});};
  function dateOption(){
    var old=$('#periodSelect option[value=day]');
    if(V7.selectedDate&&V7.selectedDate!==TODAY){
      if(!old){old=document.createElement('option');old.value='day';$('#periodSelect').appendChild(old);}
      old.textContent=selectedDateLabel();
    }else if(old)old.remove();
    $('#periodSelect').value=V6.period;
  }
  function renderFilters(){
    var all=rangeEvents();
    $('#calendarLegend').innerHTML='<button class="v7-filter'+(!V7.types.length?' on':'')+'" data-v7="all-types" aria-pressed="'+(!V7.types.length)+'">'+L('全部','All')+'<span class="qty">'+all.length+'</span></button>'+
      kindOrder.map(function(k){
        var on=V7.types.includes(k),n=all.filter(function(e){return e.kind===k;}).length;
        return '<button class="v7-filter'+(on?' on':'')+'" data-v7="type" data-kind="'+k+'" aria-pressed="'+on+'" aria-label="'+L('筛选：','Filter: ')+categoryName(k)+'" title="'+categoryName(k)+'">'+glyph(k)+'<span>'+L(CAT[k],k==='maint'?'Maint.':categoryEn[k])+'</span><span class="qty">'+n+'</span></button>';
      }).join('');
    $('#calendarLegend').setAttribute('aria-label',L('按事项类型筛选，可多选','Filter by item type; multiple selection allowed'));
  }
  renderMonthList=function(){
    dateOption();
    var list=periodEvents(),all=rangeEvents(),filtered=V7.types.length>0;
    $('#periodCount').textContent=L(list.length+' 项',list.length+' items');
    var notice=filtered?'<div class="v7-filter-notice"><span>'+L('已筛选：','Filtered: ')+V7.types.map(categoryName).join(L('、',', '))+'</span><button data-v7="all-types">'+L('清除筛选','Clear filters')+'</button></div>':'';
    var heading=L(V6.period==='day'?'当天暂无事项':V6.period==='today'?'今日暂无事项':V6.period==='week'?'本周暂无事项':'本月暂无事项',V6.period==='day'?'No items on this date':V6.period==='today'?'No items today':V6.period==='week'?'No items this week':'No items this month');
    var empty='<div class="empty v6-empty v7-filter-empty"><div class="eo">'+icon('bell')+'</div><h3>'+(filtered?L('没有匹配的事项','No matching items'):heading)+'</h3><p>'+(filtered?L('当前范围有 '+all.length+' 项，试试其他类型或清除筛选。','There are '+all.length+' items in this date range. Try another type or clear the filters.'):!hasTeam()?emptyCopy():L('可点击其他日期，或添加个人待办。','Select another date or add a personal to-do.'))+'</p>'+(filtered?'<button class="btn ghost" data-v7="all-types">'+L('显示全部类型','Show all types')+'</button>':!hasTeam()?emptyAction():'')+'</div>';
    $('#alertList').style.display='block';$('#alertList').innerHTML=notice+(list.length?list.map(eventHtml).join(''):empty);
    $('#alertEmpty').hidden=true;$('#alertEmpty').style.display='none';
    renderFilters();requestLanguage();
  };
  var v7RenderCal=renderCal;
  renderCal=function(){
    v7RenderCal();
    var events=allEvents();
    $$('#calGrid [data-d]').forEach(function(btn){
      var ev=events.filter(function(e){return e.date===btn.dataset.d&&(!V7.types.length||V7.types.includes(e.kind));});
      var kinds=kindOrder.filter(function(k){return ev.some(function(e){return e.kind===k;});});
      btn.querySelector('.v6-day-glyphs').innerHTML=kinds.map(glyph).join('');
      btn.setAttribute('aria-label',btn.dataset.d+' · '+(kinds.length?kinds.map(categoryName).join(', '):L('暂无匹配事项','No matching items')));
    });
    requestLanguage();
  };
  $('#periodSelect').addEventListener('change',function(){
    if(this.value==='today'||this.value==='week'){
      V7.selectedDate=TODAY;CAL_SEL=TODAY;CAL_Y=+TODAY.slice(0,4);CAL_M=+TODAY.slice(5,7);
    }else if(this.value==='day'&&V7.selectedDate){
      CAL_SEL=V7.selectedDate;CAL_Y=+CAL_SEL.slice(0,4);CAL_M=+CAL_SEL.slice(5,7);
    }
    renderCal();
  });
