    var rope=ROPES.find(function(r){return r.id===e.rope;});if(!rope)return;
    if(e.pending){openRope(rope.id);openRecord('insp1');return;}
    var record=allRecordCandidates().find(function(r){return r.id===e.sourceId;});
    if(!record){record=sampleRecord('EVENT-'+e.sourceId,rope.id,{maint:'维护记录',use:'使用记录',inci:'事故记录'}[e.kind],e.date,0,e.note,'—');record.review='pending';record.syncedAt='';record.regions=PARTS.map(function(p){return {name:p,note:'',photos:[],damage:[]};});}
    openRecordOverview(record,'alerts');
