  function fileLabel(file){return file.name+' · '+Math.max(1,Math.round(file.size/1024))+' KB';}
  function renderTodoFiles(){
    $('#todoAttachmentsList').innerHTML=V18.todoFiles.map(function(f,i){return '<div class="v18-file-row">'+(f.type.startsWith('image/')?'<img src="'+f.data+'" alt="'+esc(f.name)+'">':icon('doc','sm'))+'<span>'+esc(fileLabel(f))+'</span><button data-v18="remove-file" data-index="'+i+'" aria-label="'+L('移除附件 ','Remove attachment ')+esc(f.name)+'">'+icon('close','sm')+'</button></div>';}).join('');
    $('#todoAttachmentFeedback').textContent=V18.fileBusy?L('正在读取附件…','Reading attachments…'):V18.todoFiles.length?L('已添加 '+V18.todoFiles.length+' 个附件',V18.todoFiles.length+' attachments added'):L('可添加照片或本地文件','Add photos or local files');
    $('#sheetTodo [data-v5="save-todo"]').disabled=V18.fileBusy>0;
  }
  ['todoPhotoInput','todoFileInput'].forEach(function(id){$('#'+id).addEventListener('change',async function(){
    var files=Array.from(this.files||[]),epoch=V18.todoEpoch;this.value='';V18.fileBusy+=files.length;renderTodoFiles();
    await Promise.all(files.map(function(file){return new Promise(function(resolve){var reader=new FileReader();reader.onload=function(){if(epoch!==V18.todoEpoch){resolve();return;}V18.todoFiles.push({name:file.name,type:file.type||'application/octet-stream',size:file.size,data:String(reader.result)});V18.fileBusy--;renderTodoFiles();resolve();};reader.onerror=function(){if(epoch!==V18.todoEpoch){resolve();return;}V18.fileBusy--;renderTodoFiles();toast(L('附件读取失败：','Could not read: ')+file.name,'bad');resolve();};reader.readAsDataURL(file);});}));
  });});
