    var gif=V18.gifs[key],still=V18.gifs[key+'Still'];
    $('#helpDetailBody').insertAdjacentHTML('afterbegin','<div class="v18-guide-demo"><div class="sec-h"><h2>'+L('操作演示','Operation demo')+'</h2><button data-v18="guide-toggle" id="guideToggle">'+L('暂停','Pause')+'</button></div>'+(gif?'<img id="guideAnimation" src="'+gif+'" alt="'+L('操作步骤演示','Animated operation steps')+'">':'<div class="v18-guide-placeholder">'+L('操作演示准备中','Preparing operation demo')+'</div>')+'<p>'+L(key==='app'?'选择缆绳 → 新增记录 → 检查与保存':key==='nfc'?'打开NFC → 扫描标签 → 查看档案':'离线保存 → 联网同步 → 查看结果',key==='app'?'Choose rope → new record → inspect and save':key==='nfc'?'Open NFC → scan tag → view record':'Save offline → reconnect → check sync')+'</p></div>');
