  shareText=function(){
    if(!activeRope)return '';var r=activeRope,m=ropeMeta(r),selected=V18.share;if(!Object.values(selected).some(Boolean))return '';
    var lines=['ID-Tag 2.0 · '+r.name];
    if(selected.info){var d=ROPE_DETAIL[r.id]||{};lines.push('',L('【缆绳信息】','[Rope information]'),'NFC: '+r.id,L('产品编号：','Product ID: ')+pendingValue(d.code),L('制造商：','Manufacturer: ')+r.maker,L('位置：','Location: ')+r.loc,L('负责人：','Responsible member: ')+(r.crew||'—'),L('证书日期：','Certificate date: ')+pendingValue(m.certDate),L('出厂日期：','Manufacture date: ')+pendingValue(d.mfg),L('安装日期：','Installation date: ')+pendingValue(d.inst),L('最近检查：','Last inspection: ')+(r.last||'—'),L('下次检查：','Next inspection: ')+r.due,L('证书到期：','Certificate expiry: ')+pendingValue(m.certExpiry));}
    if(selected.spec)lines.push('',L('【规格】','[Specifications]'),L('缆绳名称：','Rope: ')+m.name,L('材质：','Material: ')+pendingValue(m.material),L('结构：','Construction: ')+pendingValue(m.structure),L('直径：','Diameter: ')+pendingValue(m.diameter)+' mm',L('最小破断力：','Minimum breaking load: ')+pendingValue(m.mbl)+' kN',L('线密度：','Linear density: ')+pendingValue(m.density)+' g/m',L('长度：','Length: ')+pendingValue(m.length)+' m');
    if(selected.history){lines.push('',L('【履历】','[History]'));var records=approvedRecords().filter(function(x){return x.rope===r.id;});if(!records.length)lines.push(L('暂无已审核且已同步履历','No approved, synced history'));records.forEach(function(x){lines.push(x.type+' · '+x.date+' · '+L('检查人：','Inspector: ')+x.by);if(canReadRecordDetails()&&x.look)lines.push(x.look);});if(!canReadRecordDetails())lines.push(L('仅分享履历基本信息，详情按授权查看。','Only basic history is shared; details require access.'));}
    return lines.join('\n');
  };
