  function deadlineDates(rope){var d=ROPE_DETAIL[rope.id]||{};return {routine:rope.due||'',detailed:d.detailedDue||'',certificate:d.certExpiry||''};}
  function recordKind(r){return /详细检查/.test(r.type)?'detailed':/常规检查/.test(r.type)?'routine':'';}
  function recordRejected(r){return V5.auditHistory.some(function(h){return h.id===r.id&&h.result==='reject';});}
