      var source='DEADLINE-'+type+'-'+r.id+'-'+date;
      tasks.push({id:source,sourceId:source,taskKey:source,rope:r.id,checkType:type,date:date,originDate:date,dueDate:date,kind:'due',title:L(V19.types[type][0],V19.types[type][1]),note:L('档案日期：','Archive date: ')+date,pending:true,done:false});
