  function refreshRopeDateStates(){ROPES.forEach(function(r){var dates=deadlineDates(r),phases=Object.keys(dates).map(function(type){return deadlinePhase(r,type,dates[type]);});r.status=phases.includes('overdue')?'bad':phases.includes('due')?'warn':'ok';});}
