    if(q.expiry==='custom')h+='<div class="v20-date-range"><div><label for="certRangeStart">'+L('开始日期','Start date')+'</label><input id="certRangeStart" type="date" value="'+q.start+'"></div><div><label for="certRangeEnd">'+L('结束日期','End date')+'</label><input id="certRangeEnd" type="date" value="'+q.end+'"></div></div>'+(q.start&&q.end&&q.end<q.start?'<p class="v5-error" role="alert">'+L('结束日期不能早于开始日期','End date must not precede start date')+'</p>':'');
