    if(changes.some(function(c){return !/^\d{4}-\d{2}-\d{2}$/.test(c.expiry)||c.issued&&c.expiry<c.issued;})){failInline('#certValidityError',L('请选择有效的到期日，且不得早于各证书的档案日期。','Choose a valid expiry no earlier than each archive certificate date.'));return;}
