  /* ZIP store format: original file bytes, UTF-8 paths, one rope folder per file. */
  function v21MakeZip(entries){
    var table=new Uint32Array(256);for(var n=0;n<256;n++){var c=n;for(var k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;table[n]=c>>>0;}
    function crc(bytes){var c=0xFFFFFFFF;for(var i=0;i<bytes.length;i++)c=table[(c^bytes[i])&255]^(c>>>8);return (c^0xFFFFFFFF)>>>0;}
    var encoder=new TextEncoder(),locals=[],central=[],offset=0,centralSize=0,now=new Date(),dosTime=(now.getHours()<<11)|(now.getMinutes()<<5)|(now.getSeconds()>>1),dosDate=((Math.max(1980,now.getFullYear())-1980)<<9)|((now.getMonth()+1)<<5)|now.getDate();
    entries.forEach(function(e){var name=encoder.encode(e.name),bytes=e.bytes,sum=crc(bytes),header=new Uint8Array(30+name.length),h=new DataView(header.buffer);h.setUint32(0,0x04034B50,true);h.setUint16(4,20,true);h.setUint16(6,0x0800,true);h.setUint16(10,dosTime,true);h.setUint16(12,dosDate,true);h.setUint32(14,sum,true);h.setUint32(18,bytes.length,true);h.setUint32(22,bytes.length,true);h.setUint16(26,name.length,true);header.set(name,30);locals.push(header,bytes);
      var index=new Uint8Array(46+name.length),v=new DataView(index.buffer);v.setUint32(0,0x02014B50,true);v.setUint16(4,20,true);v.setUint16(6,20,true);v.setUint16(8,0x0800,true);v.setUint16(12,dosTime,true);v.setUint16(14,dosDate,true);v.setUint32(16,sum,true);v.setUint32(20,bytes.length,true);v.setUint32(24,bytes.length,true);v.setUint16(28,name.length,true);v.setUint32(42,offset,true);index.set(name,46);central.push(index);centralSize+=index.length;offset+=header.length+bytes.length;
    });
    var end=new Uint8Array(22),d=new DataView(end.buffer);d.setUint32(0,0x06054B50,true);d.setUint16(8,entries.length,true);d.setUint16(10,entries.length,true);d.setUint32(12,centralSize,true);d.setUint32(16,offset,true);return new Blob(locals.concat(central,[end]),{type:'application/zip'});
  }
  async function v21DownloadSelected(){
    var files=v21SelectedFiles();if(!files.length||V21.zipBusy)return;V21.zipBusy=true;v21UpdateBulkbar();await new Promise(requestAnimationFrame);
    try{var entries=files.map(function(f){var a=V15.assets[f.key],raw=atob(a.data),bytes=Uint8Array.from(raw,function(c){return c.charCodeAt(0);}),folder=f.rope.id.replace(/[\\/:*?"<>|]/g,'_').replace(/\.\./g,'_');return {name:folder+'/'+a.name,bytes:bytes};});
      var blob=v21MakeZip(entries),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ID-Tag_证书_'+files.length+'份.zip';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},60000);toast(L('已生成 '+files.length+' 份证书的ZIP下载','ZIP download prepared for '+files.length+' certificates'));
    }catch(err){toast(L('打包失败，请重试。','Could not create the ZIP. Try again.'),'bad');}finally{V21.zipBusy=false;v21UpdateBulkbar();}
  }

